@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + researchKeywords : string[]
}

class Institution {
  + institutionCode : int
  + address : string
}

class ScientificArticle {
  + DOI : string
  + title : string
  + authors : Person[]
  + position : int[]
}

class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
  + reviewers : Person[]
}

class TechnicalReport extends ScientificArticle {
  + publisher : Institution
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + publisher : Publisher
  + impactFactor : float
}

Person --|> Institution
ScientificArticle "1" -- "0..*" Person
PeerReviewedPaper --|> ScientificArticle
TechnicalReport --|> ScientificArticle
Publisher "1" *-- "0..*" Journal

@enduml

